import { describe, expect, it } from 'vitest';
import { describeU, uBand } from '../src/services/u-reading.ts';

/**
 * U-reading thresholds (also stated in the PR body):
 * U > 1.5 -> non isolé · 0.8 < U <= 1.5 -> peu isolé · 0.4 < U <= 0.8 ->
 * isolation moyenne · 0.2 < U <= 0.4 -> bonne isolation · U <= 0.2 ->
 * très bonne isolation.
 */
describe('describeU (plain-language U reading)', () => {
  it('maps the bands, including the boundaries', () => {
    expect(uBand(1.6393)).toBe('non-isole');
    expect(uBand(1.5)).toBe('peu-isole');
    expect(uBand(0.8)).toBe('moyen');
    expect(uBand(0.4)).toBe('bon');
    expect(uBand(0.2)).toBe('tres-bon');
    expect(uBand(0.05)).toBe('tres-bon');
    expect(uBand(4)).toBe('non-isole');
  });

  it('produces the plain-language phrases (audit examples: "mur non isolé", "isolation moyenne", "très bonne isolation")', () => {
    expect(describeU(1.6393, 'mur', 'm')).toBe('mur non isolé');
    expect(describeU(1.0, 'mur', 'm')).toBe('mur peu isolé');
    expect(describeU(0.6, 'mur', 'm')).toBe('isolation moyenne');
    expect(describeU(0.3, 'mur', 'm')).toBe('bonne isolation');
    expect(describeU(0.2, 'mur', 'm')).toBe('très bonne isolation');
  });

  it('agrees on feminine nouns (toiture, baie vitrée)', () => {
    expect(describeU(2, 'toiture', 'f')).toBe('toiture non isolée');
    expect(describeU(1.2, 'baie vitrée', 'f')).toBe('baie vitrée peu isolée');
  });

  it('returns an empty reading for non-finite or non-positive values (nothing claimed)', () => {
    expect(describeU(Number.NaN)).toBe('');
    expect(describeU(Number.POSITIVE_INFINITY)).toBe('');
    expect(describeU(-1, 'mur', 'm')).toBe('');
    expect(describeU(0, 'mur', 'm')).toBe('');
    expect(uBand(Number.NaN)).toBeNull();
  });
});

import type { ReactNode } from 'react';
import { Box, Chip, Divider, Paper, Typography, useTheme } from '@mui/material';
import { useViewerStore } from '../store/viewer-store.ts';
import { confidenceInWords } from '../services/confidence-words.ts';
import { ConfidenceBadge } from './ConfidenceBadge.tsx';
import type { ConfidenceJson } from '../types.ts';

/**
 * Side panel showing the properties of the selected element (FR-P3-03):
 * id, kind, label, plain-words provenance chip, U-value, area, orientation,
 * placement — each value annotated « mesuré par le DPE » vs « estimé — à
 * vérifier » with the raw source behind « d'où vient cette valeur ? »
 * (UX audit F6 / US 7). Pure presentation of store data, laid out as a
 * definition list with the theme border radius (UI audit F12).
 */

function Row({ term, testId, children }: Readonly<{ term: string; testId?: string; children: ReactNode }>) {
  return (
    <Box sx={{ display: 'flex', gap: 1, py: 0.25 }}>
      <Box component="dt" sx={{ width: 96, flexShrink: 0, color: 'text.secondary', fontSize: 13 }}>
        {term}
      </Box>
      <Box component="dd" data-testid={testId} sx={{ m: 0, fontSize: 13, overflowWrap: 'anywhere' }}>
        {children}
      </Box>
    </Box>
  );
}

/** Renders a value followed by its plain-words confidence badge. */
function ValueWithConfidence({
  text,
  value,
  testId
}: Readonly<{ text: string; value: ConfidenceJson<unknown>; testId: string }>) {
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
      <span>{text}</span>
      <ConfidenceBadge value={value} testId={testId} />
    </Box>
  );
}

export function ElementPanel() {
  const theme = useTheme();
  const geometry = useViewerStore((s) => s.geometry);
  const selectedElementId = useViewerStore((s) => s.selectedElementId);
  const element = geometry?.elements.find((el) => el.id === selectedElementId) ?? null;

  return (
    <Paper
      data-testid="element-panel"
      elevation={3}
      sx={{
        width: { xs: '100%', md: 320 },
        maxHeight: { xs: '38vh', md: 'none' },
        p: 2,
        overflowY: 'auto',
        borderRadius: theme.shape.borderRadius
      }}
    >
      <Typography variant="h6" component="h2">
        Élément sélectionné
      </Typography>
      {element === null ? (
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          Cliquez sur un élément du modèle 3D pour voir ses propriétés.
        </Typography>
      ) : (
        <Box component="dl" sx={{ m: 0, mt: 1 }}>
          <Row term="id" testId="element-id">
            {element.id}
          </Row>
          <Row term="type">{element.kind}</Row>
          <Row term="label">{element.label}</Row>
          <Box sx={{ py: 0.5 }}>
            <Chip
              size="small"
              color={element.inferred ? 'warning' : 'success'}
              label={confidenceInWords({ source: element.placement.source, confidence: element.placement.confidence })}
              data-testid={element.inferred ? 'element-inferred' : 'element-measured'}
            />
          </Box>
          <Divider sx={{ my: 1 }} />
          <Row term="surface" testId="element-area">
            {element.areaM2 === null ? (
              '—'
            ) : (
              <ValueWithConfidence text={`${element.areaM2.value} m²`} value={element.areaM2} testId="element-area-source" />
            )}
          </Row>
          <Row term="U" testId="element-uvalue">
            {element.uValueWm2K === null ? (
              '—'
            ) : (
              <ValueWithConfidence
                text={`${element.uValueWm2K.value} W/m².K`}
                value={element.uValueWm2K}
                testId="element-uvalue-source"
              />
            )}
          </Row>
          <Row term="orientation" testId="element-orientation">
            {element.orientation === null ? (
              '—'
            ) : (
              <ValueWithConfidence
                text={String(element.orientation.value)}
                value={element.orientation}
                testId="element-orientation-source"
              />
            )}
          </Row>
          <Row term="placement" testId="element-confidence-row">
            <ConfidenceBadge value={element.placement} testId="element-confidence" />
          </Row>
        </Box>
      )}
    </Paper>
  );
}

import type { BuildingCommandJson } from '../types.ts';
import type { EnumLabelKind } from '../services/enum-labels.ts';

/**
 * Command catalog (P5 headless, built on the frozen P4 command vocabulary) —
 * DATA, not UI.
 *
 * Each entry describes one typed command the user can add to a scenario:
 * wall insulation, roof insulation, floor insulation, window replacement,
 * boiler (heating system) replacement, ventilation change. The `type` tags
 * are the versioned P4 vocabulary (`building.<element>.update.v1`); P4's
 * editor renders its forms over the same vocabulary. The `buildingId` is
 * stamped server-side from the URL.
 */
export interface CommandCatalogEntry {
  readonly type: string;
  readonly label: string;
  readonly description: string;
  /** which building collection provides the target element ids */
  readonly targetKind: 'walls' | 'roofs' | 'floors' | 'windows' | 'heatingSystems' | 'ventilationSystems';
  readonly targetIdField: string;
  readonly fields: readonly CommandCatalogField[];
}

export interface CommandCatalogField {
  readonly key: string;
  readonly label: string;
  readonly input: 'number' | 'text';
  readonly placeholder?: string;
  /**
   * Min/max bounds shown on numeric inputs. Presentation data only — these
   * mirror the domain invariants `U_VALUE_MAX` etc. (packages/domain/src/commands.ts);
   * the domain remains the enforcing layer (400 fieldErrors). 0 is exclusive
   * for U values: the valid range is (0, 4] W/m².K.
   */
  readonly min?: number;
  readonly max?: number;
  /** when set, the field is a DPE enum rendered as a labeled select (raw id still sent) */
  readonly enumKind?: EnumLabelKind;
  /** plain-language example promoted from the catalog description into helper text */
  readonly helper?: string;
}

