const LABEL_COLORS: Record<string, string> = {
  A: '#1a9850',
  B: '#66bd63',
  C: '#a6d96a',
  D: '#fee08b',
  E: '#fdae61',
  F: '#f46d43',
  G: '#d73027'
};

function LabelChip({ label, testId }: { readonly label: string; readonly testId: string }) {
  return (
    <Chip
      label={label}
      data-testid={testId}
      size="small"
      sx={{ backgroundColor: LABEL_COLORS[label] ?? '#999', color: '#111', fontWeight: 700 }}
    />
